import{_ as l,a0 as p,w as r,s as n,ao as d,I as o,x as i,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"文件系統層次標準（FHS）簡介 | LCTT x X-CMD","titleTemplate":false,"description":"文件系統層次標準（FHS）簡介 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"文件系統層次標準（FHS）簡介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"文件系統層次標準（FHS）簡介 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170711 The Filesystem Hierarchy Standard Shows Which Bits Are Boss","title":"文件系統層次標準（FHS）簡介","tag":"201708","desc":""},"relativePath":"201708/20170711 The Filesystem Hierarchy Standard Shows Which Bits Are Boss.md","filePath":"[post].md"}'),h={name:"201708/20170711 The Filesystem Hierarchy Standard Shows Which Bits Are Boss.md"};function c(u,e,g,b,m,f){const s=p("Link");return r(),n("div",null,[e[16]||(e[16]=d('<h1 id="文件系統層次標準-fhs-簡介" tabindex="-1">文件系統層次標準（FHS）簡介 <a class="header-anchor" href="#文件系統層次標準-fhs-簡介" aria-label="Permalink to “文件系統層次標準（FHS）簡介”">​</a></h1><p><img src="http://www.linuxinsider.com/article_images/story_graphics_xlarge/xl-2016-linux-1.jpg" alt="linux"></p><p>當你好奇地看着系統的根目錄（<code>/</code>）的時候，可能會發現自己有點不知所措。大多數三個字母的目錄名稱並沒有告訴你它們是做什麼的，如果你需要做出一些重要的修改，那就很難知道在哪裏可以查看。</p><p>我想給那些沒有深入瞭解過自己的根目錄的人簡單地介紹下它。</p><h3 id="有用的工具" tabindex="-1">有用的工具 <a class="header-anchor" href="#有用的工具" aria-label="Permalink to “有用的工具”">​</a></h3><p>在我們開始之前，這裏有幾個需要熟悉的工具，它們可以讓您隨時挖掘那些您自己找到的有趣的東西。這些程序都不會對您的文件進行任何更改。</p><p>最有用的工具是 <code>ls</code> -- 它列出了使用完整路徑或相對路徑（即從當前目錄開始的路徑）作為參數給出的任何目錄的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls  路徑</span></span></code></pre></div><p>當您進一步深入文件系統時，重複輸入長路徑可能會變得很麻煩，所以如果您想簡化這一操作，可以用 <code>cd</code> 替換 <code>ls</code> 來更改當前的工作目錄到該目錄。與 <code>ls</code> 一樣，只需將目錄路徑作為 <code>cd</code> 的參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd  路徑</span></span></code></pre></div><p>如果您不確定某個文件是什麼文件類型的，可以通過運行 <code>file</code> 並且將文件名作為 <code>file</code> 命令的參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file  文件名</span></span></code></pre></div><p>最後，如果這個文件看起來像是適宜閲讀的，那麼用 <code>less</code> 來看看（不用擔心文件有改變）。與最後一個工具一樣，給出一個文件名作為參數來查看它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ less  文件名</span></span></code></pre></div><p>完成文件翻閲後，點擊 <code>q</code> 鍵退出，即可返回到您的終端。</p><h3 id="根目錄之旅" tabindex="-1">根目錄之旅 <a class="header-anchor" href="#根目錄之旅" aria-label="Permalink to “根目錄之旅”">​</a></h3><p>現在就開始我們的旅程。我將按照字母順序介紹直接放在根目錄下的目錄。這裏並沒有介紹所有的目錄，但到最後，我們會突出其中的亮點。</p>',17)),o("p",null,[e[1]||(e[1]=i("我們所有要遍歷的目錄的分類及功能都基於 Linux 的文件系統層次標準（FHS）。",-1)),t(s,{href:"http://www.linuxfoundation.org/"},{default:a(()=>[...e[0]||(e[0]=[i("Linux 基金會",-1)])]),_:1}),e[2]||(e[2]=i("維護的 Linux FHS 幫助發行版和程序的設計者和開發人員來規劃他們的工具的各個組件應該存放的位置。",-1))]),e[17]||(e[17]=d('<p>通過將各個程序的所有文件、二進制文件和幫助手冊保存在一致的組織結構中，FHS 讓對它們的學習、調試或修改更加容易。想像一下，如果不是使用 <code>man</code> 命令找到使用指南，那麼你就得對每個程序分別尋找其手冊。</p><p>按照字母順序和結構順序，我們從 <code>/bin</code> 開始。該目錄是存放所有核心繫統二進制文件的地方，其包含的命令可以在 shell （解釋終端指令的程序）中使用。沒有這個目錄的內容，你的系統就基本沒法使用。</p><p>接下來是 <code>/boot</code> 目錄，它存儲了您的計算機啓動所需的所有東西。其中最重要的是引導程序和內核。引導程序是一個通過初始化一些基礎工具，使引導過程得以繼續的程序。在初始化結束時，引導程序會加載內核，內核允許計算機與所有其它硬件和固件進行接口。從這一點看，它可以使整個操作系統工作起來。</p><p><code>/dev</code> 目錄用於存儲類似文件的對象來表示被系統識別為“設備”的各種東西。這裏包括許多顯式的設備，如計算機的硬件組件：鍵盤、屏幕、硬盤驅動器等。</p><p>此外，<code>/dev</code> 還包含被系統視為“設備”的數據流的偽文件。一個例子是流入和流出您的終端的數據，可以分為三個“流”。它讀取的信息被稱為“標準輸入”。命令或進程的輸出是“標準輸出”。最後，被分類為調試信息的輔助性輸出指向到“標準錯誤”。終端本身作為文件也可以在這裏找到。</p><p><code>/etc</code>（發音類似工藝商業網站 “Etsy”，如果你想讓 Linux 老用户驚豔一下的話，囧），許多程序在這裏存儲它們的配置文件，用於改變它們的設置。一些程序存儲這裏的是默認配置的副本，這些副本將在修改之前複製到另一個位置。其它的程序在這裏存儲配置的唯一副本，並期望用户可以直接修改。為 root 用户保留的許多程序常用一種配置模式。</p><p><code>/home</code> 目錄是用户個人文件所在的位置。對於桌面用户來説，這是您花費大部分時間的地方。對於每個非特權用户，這裏都有一個具有相應名稱的目錄。</p><p><code>/lib</code> 是您的系統賴以運行的許多庫的所在地。許多程序都會重複使用一個或多個功能或子程序，它們經常會出現在幾十上百個程序中。所以，如果每個程序在其二進制文件中重複寫它需要的每一個組件，結果會是產生出一些大而無當的程序，作為更好的替代方案，我們可以通過進行“庫調用”來引用這些庫中的一個或多個。</p><p>在 <code>/media</code> 目錄中可以訪問像 USB 閃存驅動器或攝像機這樣的可移動媒體。雖然它並不是所有系統上都有，但在一些專注於直觀的桌面系統中還是比較普遍的，如 Ubuntu。具有存儲能力的媒體在此處被“掛載”，這意味着當設備中的原始位流位於 <code>/dev</code> 目錄下時，用户通常可以在這裏訪問那些可交互的文件對象。</p><p><code>/proc</code> 目錄是一個動態顯示系統數據的虛擬文件系統。這意味着系統可以即時地創建 <code>/proc</code> 的內容，用包含運行時生成的系統信息（如硬件統計信息）的文件進行填充。</p><p><code>/tmp</code> 正如其名字，用於放置緩存數據等臨時信息。這個目錄不做其他更多的事情。</p><p>現代 Linux 系統上大多數程序的二進制文件保存在 <code>/usr</code> 目錄中。為了統一包含二進制文件的各種目錄，<code>/usr</code> 包含 <code>/bin</code>、<code>/sbin</code> 和 <code>/lib</code> 中的所有內容的副本。</p><p>最後，<code>/var</code> 裏保存“<ruby>可變<rt>variable</rt></ruby>”長度的數據。這裏的可變長度數據的類型通常是會累積的數據，就像日誌和緩存一樣。一個例子是你的內核保留的日誌。</p><p>為了避免硬盤空間用盡和崩潰的情況，<code>/var</code> 內置了“日誌旋轉”功能，可刪除舊信息，為新信息騰出空間，維持固定的最大大小。</p><h3 id="結尾" tabindex="-1">結尾 <a class="header-anchor" href="#結尾" aria-label="Permalink to “結尾”">​</a></h3><p>正如我所説，這裏介紹的絕對不是您在根目錄中可以找到的一切，但是確定系統核心功能所在地是一個很好的開始，而且可以更深入地研究這些功能是什麼。</p><p>所以，如果你不知道要學習什麼，就可能有很多的想法。如果你想得到一個更好的想法，就在這些目錄中折騰自己吧！</p><hr><p>作者簡介：</p><p>自 2017 年以來 Jonathan Terrasi 一直是 ECT 新聞網的專欄作家。他的主要興趣是計算機安全（特別是 Linux 桌面），加密和分析政治和時事。他是全職自由作家和音樂家。他的背景包括在芝加哥委員會發表的保衞人權法案文章中提供技術評論和分析。</p><hr>',21)),o("p",null,[e[4]||(e[4]=i("via: ",-1)),t(s,{href:"http://www.linuxinsider.com/story/84658.html"},{default:a(()=>[...e[3]||(e[3]=[i("http://www.linuxinsider.com/story/84658.html",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=i("作者：",-1)),t(s,{href:"http://www.linuxinsider.com/perl/mailit/?id=84658"},{default:a(()=>[...e[5]||(e[5]=[i("Jonathan Terrasi",-1)])]),_:1}),e[9]||(e[9]=i(" 譯者：",-1)),t(s,{href:"https://github.com/firmianay"},{default:a(()=>[...e[6]||(e[6]=[i("firmianay",-1)])]),_:1}),e[10]||(e[10]=i(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[7]||(e[7]=[i("wxy",-1)])]),_:1})]),o("p",null,[e[13]||(e[13]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[11]||(e[11]=[i("LCTT",-1)])]),_:1}),e[14]||(e[14]=i(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:a(()=>[...e[12]||(e[12]=[i("Linux中國",-1)])]),_:1}),e[15]||(e[15]=i(" 榮譽推出",-1))])])}const y=l(h,[["render",c]]);export{T as __pageData,y as default};
